    /** A Lucide icon in a [frame] unit square, its paths placed there and stroked [width] wide. */
    private fun lucide(name: String, frame: Float, width: Float, vararg paths: String): ImageVector =
        lucide(name, frame, frame, width, *paths)

    /** A Lucide icon in a [frameWidth] x [frameHeight] unit frame. */
    private fun lucide(name: String, frameWidth: Float, frameHeight: Float, width: Float, vararg paths: String): ImageVector {
        val b = ImageVector.Builder(name = name, defaultWidth = frameWidth.dp, defaultHeight = frameHeight.dp, viewportWidth = frameWidth, viewportHeight = frameHeight)
        for (d in paths) {
            b.addPath(
                pathData = addPathNodes(d),
                stroke = SolidColor(Color.White),
                strokeLineWidth = width,
                strokeLineCap = StrokeCap.Round,
                strokeLineJoin = StrokeJoin.Round,
            )
        }
        return b.build()
    }
